using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json.Nodes;
using Ged.Core.Compiler;
using Ged.Core.Editor;
using Ged.Core.Model;
using Ged.Core.Spatial;
using Xunit;
using Xunit.Abstractions;
using static Ged.Core.Tests.Scripting.KitLayoutHarness;

namespace Ged.Core.Tests.Scripting;

/// <summary>
/// The Q4 gate (DESIGN-QUALITY-SPEC §(g)): seeded layouts per gametype × class (dm, ctf, koth × standard, open_air,
/// plus payload), each generated by kit.layout and built by kit.build_layout on a File ▸ New level. Every one builds with
/// zero holes on the SEALED Shared BSP build; the grader's flow checks (G12-G14; C01 for CTF, K01 for KOTH; P01-P03 and
/// P05-P07 for payload — P04 is population, chunk Q5) all pass in at least 95% of the layouts; and the hard checks G24
/// (too simple) and G25 (samey / confusing) never fail. The players cycle through the size classes by seed. Measured pass
/// rates and every layout's verdict are written to tests/artifacts/kit_layout/gate_&lt;gametype&gt;_&lt;class&gt;.txt.
/// </summary>
/// <remarks>One class per gametype × class, so the seven gates run as separate test collections (in parallel when the
/// runner allows it). By default each runs seeds 1-3 (about 2-10 minutes in all on an idle machine); the full §(g) gate
/// is <c>GED_LAYOUT_GATE_SEEDS=20</c> (about an hour; run it serially on an idle box like a Perf stage).</remarks>
public abstract class KitLayoutGateTests
{
    /// <summary>Seeds per combination: GED_LAYOUT_GATE_SEEDS (the §(g) gate is 20), else 3.</summary>
    private static int Seeds => int.TryParse(Environment.GetEnvironmentVariable("GED_LAYOUT_GATE_SEEDS"), out int n) && n > 0 ? n : 3;

    private readonly ITestOutputHelper _out;

    protected KitLayoutGateTests(ITestOutputHelper output) => _out = output;

    protected void Gate(string gametype, string cls)
    {
        string[] flow = FlowChecks(gametype);
        var perCheck = flow.ToDictionary(c => c, _ => 0, StringComparer.Ordinal);
        int allFlow = 0, holed = 0, hardFails = 0, pass = 0, review = 0;
        var log = new StringBuilder();
        var problems = new List<string>();
        string artifact = Path.Combine(ArtifactsDir(), $"gate_{gametype}_{cls}.txt");
        File.WriteAllText(artifact, $"Q4 gate {gametype}/{cls}: running" + Environment.NewLine); // each seed's line is appended as it finishes
        for (int seed = 1; seed <= Seeds; seed++)
        {
            int players = Players(gametype, seed);
            var sw = System.Diagnostics.Stopwatch.StartNew();
            (EditorDocument doc, string summary) = Build(gametype, cls, seed, players);
            (CompiledLevel shared, List<Vec3> holes) = Holes(doc, sharedBsp: true);
            JsonObject grade = Grade(doc, shared, gametype, cls, players);
            List<string> failed = DesignGrader.FailedIds(grade);
            string verdict = grade["verdict"]!.GetValue<string>();
            pass += verdict == "PASS" ? 1 : 0;
            review += verdict == "REVIEW" ? 1 : 0;
            bool flowOk = true;
            foreach (string c in flow)
            {
                if (failed.Contains(c))
                {
                    flowOk = false;
                }
                else
                {
                    perCheck[c]++;
                }
            }

            allFlow += flowOk ? 1 : 0;
            bool hard = failed.Contains("G24") || failed.Contains("G25");
            hardFails += hard ? 1 : 0;
            holed += holes.Count > 0 ? 1 : 0;
            string line = $"seed {seed,2} ({players,2} players): zones:links:violations:spawns {summary}; holes {holes.Count}; class {grade["class"]}; " +
                          $"{verdict} [{string.Join(",", failed)}]; {sw.Elapsed.TotalSeconds:0} s";
            log.AppendLine(line);
            _out.WriteLine(line);
            File.AppendAllText(artifact, line + Environment.NewLine);
            if (holes.Count > 0)
            {
                problems.Add($"seed {seed}: {holes.Count} hole(s) near " + string.Join("; ", holes.Take(3).Select(h => $"({Fmt(h.X)}, {Fmt(h.Y)}, {Fmt(h.Z)})")));
            }

            if (hard)
            {
                problems.Add($"seed {seed}: hard check failed [{string.Join(",", failed)}]");
            }
        }

        var summaryText = new StringBuilder();
        summaryText.AppendLine($"Q4 gate {gametype}/{cls}: {Seeds} layouts");
        summaryText.AppendLine($"  zero holes (sealed Shared BSP): {Seeds - holed}/{Seeds}");
        summaryText.AppendLine($"  all flow checks ({string.Join(", ", flow)}): {allFlow}/{Seeds} = {100.0 * allFlow / Seeds:0}%");
        foreach (string c in flow)
        {
            summaryText.AppendLine($"    {c}: {perCheck[c]}/{Seeds}");
        }

        summaryText.AppendLine($"  G24/G25 failures: {hardFails}");
        summaryText.AppendLine($"  verdicts: PASS {pass}, REVIEW {review}, FAIL {Seeds - pass - review} (population checks G15-G20 / P04 belong to chunk Q5)");
        string text = summaryText.ToString() + log;
        _out.WriteLine(summaryText.ToString());
        File.WriteAllText(artifact, text);

        Assert.True(holed == 0, $"{gametype}/{cls}: layouts with holes:\n" + string.Join("\n", problems));
        Assert.True(hardFails == 0, $"{gametype}/{cls}: G24/G25 failed:\n" + string.Join("\n", problems));
        Assert.True(allFlow >= Math.Ceiling(0.95 * Seeds), $"{gametype}/{cls}: the flow checks passed in {allFlow}/{Seeds} layouts (needs 95%):\n" + text);
    }
}

[Trait("Category", "DeepGate")]
public sealed class KitLayoutGateDmStandard(ITestOutputHelper output) : KitLayoutGateTests(output)
{
    [Fact]
    public void Twenty_Seeded_Layouts_Build_Watertight_And_Pass_The_Flow_Checks() => Gate("dm", "standard");
}

